skinparam nodesep 5
hide stereotype

<style>
  root {
    BackgroundColor: #ffffff;
    FontColor: #444444;
  }
  // Element
  .Element-RWxlbWVudA== {
    BackgroundColor: #ffffff;
    LineColor: #444444;
    LineStyle: 0;
    LineThickness: 2;
    FontColor: #444444;
    FontSize: 24;
    HorizontalAlignment: center;
    Shadowing: 0;
    MaximumWidth: 450;
  }
  // Relationship
  .Relationship-UmVsYXRpb25zaGlw {
    LineThickness: 2;
    LineStyle: 10-10;
    LineColor: #444444;
    FontColor: #444444;
    FontSize: 24;
  }
</style>

rectangle "==Patron\\n<size:16>[Person]</size>\\n\\nBorrows books at the library." <<Element-RWxlbWVudA==>> as Patron
rectangle "==Library\\n<size:16>[Software System]</size>\\n\\nManages books and loans." <<Element-RWxlbWVudA==>> as Library

Patron --> Library <<Relationship-UmVsYXRpb25zaGlw>> : "Browses the catalogue through\\n<size:16>[HTTPS]</size>"

@enduml`;

function toB64(buf) {
  let s = "";
  const CH = 0x8000;
  for (let i = 0; i < buf.length; i += CH) {
    s += String.fromCharCode.apply(null, buf.subarray(i, i + CH));
  }
  return btoa(s);
}

async function tryRender(text) {
  try {
    const res = await fetch("https://www.plantuml.com/plantuml/api/png", {
      method: "POST",
      headers: { "Content-Type": "text/plain" },
      body: text,
    });
    const buf = new Uint8Array(await res.arrayBuffer());
    const isPng = buf.length > 8 && buf[0] === 0x89 && buf[1] === 0x50 && buf[2] === 0x4e && buf[3] === 0x47;
    return {
      status: res.status,
      contentType: res.headers.get("content-type"),
      isPng,
      size: buf.length,
      b64: isPng ? toB64(buf) : null,
      head: isPng ? null : new TextDecoder().decode(buf.slice(0, 400)),
    };
  } catch (e) {
    return { error: String(e) };
  }
}

const c4r = await tryRender(c4);
let used = "c4plantuml";
let result = c4r;
if (!c4r.isPng) {
  used = "plantuml";
  result = await tryRender(plain);
}
return { used, result: { status: result.status, contentType: result.contentType, isPng: result.isPng, size: result.size, head: result.head, b64: result.b64 } };

